def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0

    while True:
        consumed_comma = False

        if i < n and line[i] == '"':
            # quoted field
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote, must be comma or end of line
            if i < n:
                if line[i] == ',':
                    i += 1
                    consumed_comma = True
                else:
                    return None
            fields.append(''.join(chars))
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            field = line[start:i]
            if '"' in field:
                return None
            fields.append(field)
            if i < n and line[i] == ',':
                i += 1
                consumed_comma = True

        if consumed_comma:
            if i == n:
                fields.append('')
                break
            else:
                continue
        else:
            break

    return fields

